update oms_order
set status=#{status}
where id in

    #{id}

UPDATE pms_sku_stock
SET lock_stock = COALESCE(lock_stock,0) + #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND COALESCE(stock,0) - GREATEST(COALESCE(lock_stock,0),0) >= #{quantity}

UPDATE pms_sku_stock
SET stock = GREATEST(COALESCE(stock,0) - #{quantity},0),
    lock_stock = GREATEST(COALESCE(lock_stock,0) - #{quantity},0)
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND COALESCE(stock,0) >= #{quantity}
  AND GREATEST(COALESCE(lock_stock,0),0) >= #{quantity}

UPDATE pms_sku_stock
SET lock_stock = GREATEST(COALESCE(lock_stock,0) - #{quantity},0)
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND GREATEST(COALESCE(lock_stock,0),0) >= #{quantity}

UPDATE oms_order
SET status = 1, payment_time = NOW(), pay_type = #{payType}
WHERE id = #{orderId} AND status = 0 AND delete_status = 0
